  const existingIds = new Set((window.DND_SPELLS || []).map(s => s.id.toLowerCase()));
  const toSlug = (str) => str.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

  rawSpells.forEach(row => {
    const [level, name_en, name_pl, school, classes, time, range, components, duration, ritual, conc, dice, damage_type, desc_pl] = row;
    const id = toSlug(name_en);
    if (!existingIds.has(id)) {
      existingIds.add(id);
      window.DND_SPELLS.push({
        id,
        name_pl,
        name_en,
        level,
        school,
        classes,
        time,
        range,
        components,
        duration,
        ritual: Boolean(ritual),
        concentration: Boolean(conc),
        dice,
        damage_type,
        desc_pl,
        desc_en: desc_pl
      });
    }
  });
